/* Local test-host for electron-updater manifests generated by electron-builder.
 * On Windows: npm run test:update-host, configure the installed app's update source
 * to http://127.0.0.1:8990 ONLY when dev testing has been explicitly enabled.
 * Distribution must use an HTTPS origin with code signing.
 */
const http=require('node:http');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../dist');
const map={'.yml':'text/yaml','.exe':'application/octet-stream','.blockmap':'application/octet-stream'};
http.createServer((req,res)=>{
  const name=decodeURIComponent(req.url.split('?')[0]).replace(/^\//,'');
  if(!/^[\w.\- ]+$/.test(name)){res.writeHead(400);res.end('Invalid filename');return;}
  const file=path.join(root,name);
  if(!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404);res.end('Not found');return;}
  res.writeHead(200,{'Content-Type':map[path.extname(file)]||'application/octet-stream','Content-Length':fs.statSync(file).size});
  fs.createReadStream(file).pipe(res);
}).listen(8990,'127.0.0.1',()=>console.log('Local update test feed: http://127.0.0.1:8990'));
